import { dirname, join, relative, sep } from "node:path";
import type { ParsedTpl } from "./validate.ts";

interface RenderIndexOptions {
  /**
   * Controlled `topics` vocabulary. Sections follow this order; topics outside
   * it (or every topic, when it is empty) follow in alphabetical order.
   */
  topics: readonly string[];
  /** Directory holding the TPL files. */
  tplDir: string;
  /** Path of the index file being rendered; links are relative to its directory. */
  indexPath: string;
}

const HEADER = [
  "# TPL index",
  "",
  "<!-- Generated by `tpl regenerate` from TPL frontmatter. Do not edit by hand:",
  "     re-run `tpl regenerate` instead, which also resolves a merge conflict here. -->",
  "",
  "Active TPLs grouped by `topic`, then deprecated ones.",
];

/** Order ids by their digits, so `TPL-999` sorts before `TPL-1000`. */
function compareIds(a: ParsedTpl, b: ParsedTpl): number {
  return a.fm.id.localeCompare(b.fm.id, "en", { numeric: true });
}

function origins(tpl: ParsedTpl): string[] {
  const entries = Array.isArray(tpl.fm.discovered_from) ? tpl.fm.discovered_from : [];
  return entries.flatMap((e) => (e && typeof e.issue === "string" ? [e.issue] : []));
}

function entryLine(tpl: ParsedTpl, opts: RenderIndexOptions): string {
  const href = relative(dirname(opts.indexPath), join(opts.tplDir, tpl.file)).split(sep).join("/");
  const title = String(tpl.fm.title ?? "")
    .replace(/\s+/g, " ")
    .trim();
  const from = origins(tpl);
  const suffix = from.length > 0 ? ` (${from.join(", ")})` : "";
  return `- [${tpl.fm.id}](${href}) — ${title}${suffix}`;
}

function section(heading: string, tpls: readonly ParsedTpl[], opts: RenderIndexOptions): string[] {
  return ["", `## ${heading}`, "", ...[...tpls].sort(compareIds).map((t) => entryLine(t, opts))];
}

/**
 * Render the TPL index: one `## <topic>` section per topic that has an active
 * TPL, then a `## Deprecated` section. Every TPL appears exactly once, so the
 * output also satisfies `tpl validate`'s index check.
 *
 * Grouping is what keeps concurrent branches apart: ids grow monotonically, so
 * a single list puts every new entry at the same tail and two branches adding
 * a TPL always conflict. With sections, they conflict only when both add to
 * the same topic.
 */
export function renderIndex(parsed: readonly ParsedTpl[], opts: RenderIndexOptions): string {
  const byTopic = new Map<string, ParsedTpl[]>();
  const deprecated: ParsedTpl[] = [];
  for (const tpl of parsed) {
    if (tpl.fm.status === "deprecated") {
      deprecated.push(tpl);
      continue;
    }
    const topic = typeof tpl.fm.topic === "string" && tpl.fm.topic !== "" ? tpl.fm.topic : "(none)";
    const list = byTopic.get(topic);
    if (list) list.push(tpl);
    else byTopic.set(topic, [tpl]);
  }

  const known = opts.topics.filter((t) => byTopic.has(t));
  const rest = [...byTopic.keys()].filter((t) => !opts.topics.includes(t)).sort();

  const lines = [...HEADER];
  for (const topic of [...known, ...rest]) {
    lines.push(...section(topic, byTopic.get(topic)!, opts));
  }
  if (deprecated.length > 0) {
    lines.push(...section("Deprecated", deprecated, opts));
  }
  return `${lines.join("\n")}\n`;
}
